#!/usr/bin/env node
// Generates src/lib/learn/manifest.ts — static imports of every artifact JSON so
// Next bundles them (no runtime fs reads needed).
import { readdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '../../src/data/artifacts');
const OUT = join(dirname(fileURLToPath(import.meta.url)), '../../src/lib/learn/manifest.ts');

const books = readdirSync(ROOT).filter(b => !b.startsWith('.'));
const lines = [
  '// AUTO-GENERATED by scripts/artifacts/gen_manifest.mjs — do not edit by hand.',
  'import type { ChapterArtifacts } from "./artifacts";',
  '',
];
const entries = [];
for (const bk of books) {
  for (const f of readdirSync(join(ROOT, bk)).filter(x => x.endsWith('.json')).sort()) {
    const varName = `a_${bk}_${f.replace('.json', '').replace(/-/g, '_')}`;
    lines.push(`import ${varName} from "@/data/artifacts/${bk}/${f.replace('.json', '')}.json";`);
    entries.push(`  { book: "${bk}", file: "${f.replace('.json', '')}", data: ${varName} as unknown as ChapterArtifacts },`);
  }
}
lines.push('', 'export const ARTIFACT_MANIFEST: { book: string; file: string; data: ChapterArtifacts }[] = [', ...entries, '];', '');
writeFileSync(OUT, lines.join('\n'));
console.log(`manifest.ts written: ${entries.length} files`);
